<div class="table-responsive slaughter-table-wrap"><table class="enterprise-table slaughter-table shipment-table" data-datatable="false" aria-label="Carcasses et envois"><thead><tr><?php foreach(['reference'=>'Référence / lot','kind'=>'Catégorie','weight'=>'Poids (kg)','expiry'=>'DLC','state'=>'État'] as$key=>$label):?><th scope="col" class="<?=$key==='weight'?'num':''?>" aria-sort="none"><button type="button" data-flow-sort="<?=e($key)?>"><?=e($label)?> <span aria-hidden="true">↕</span></button></th><?php endforeach;?><th scope="col">Transport</th><th scope="col">Détails et actions</th></tr></thead><tbody data-flow-table-body>
<?php foreach($farm['slaughters'] as$s):if($s['status']!=='validated'||(float)$s['quantity_kg']<=0)continue;?><tr data-flow-item data-flow-key="stock-<?=e($s['weight_stock_id'])?>" data-kind="stock" data-state="stock<?=$s['expiry_date']<date('Y-m-d')?' expired':''?>" data-reference="<?=e($s['conversion_number'])?>" data-date="<?=e($s['converted_at'])?>" data-weight="<?=e($s['quantity_kg'])?>" data-expiry="<?=e($s['expiry_date'])?>" data-search="<?=e($s['site_name'].' '.$s['batch_number'].' '.$s['conversion_number'])?>">
<td data-label="Référence / lot"><strong><?=e($s['conversion_number'])?></strong><small><?=e($s['site_name'])?></small><small><?=e($s['batch_number'])?></small></td><td data-label="Catégorie">Stock ferme</td><td class="num" data-label="Poids (kg)"><strong><?=$kg($s['quantity_kg'])?></strong><small class="shipment-weight-note">physiques</small></td><td data-label="DLC"><?=e(date('d/m/Y',strtotime($s['expiry_date'])))?></td><td data-label="État"><span class="ui-status ui-status--<?=$s['expiry_date']<date('Y-m-d')?'danger':'success'?>"><?=$s['expiry_date']<date('Y-m-d')?'DLC dépassée':'Stock ferme'?></span></td><td data-label="Transport">—</td><td data-label="Détails et actions"><details class="slaughter-row-actions shipment-stock-detail"><summary>Voir le stock</summary><dl class="shipment-detail-list"><div><dt>Réservé</dt><dd><?=$kg($s['reserved_kg'])?> kg</dd></div><div><dt>Non réservé</dt><dd><?=$kg((float)$s['quantity_kg']-(float)$s['reserved_kg'])?> kg</dd></div><div><dt>Abattage</dt><dd><?=e(date('d/m/Y H:i',strtotime($s['converted_at'])))?></dd></div></dl></details></td></tr><?php endforeach;?>
<?php foreach($farm['shipments'] as$t):?><tr data-shipment-id="<?=e($t['id'])?>" data-flow-item data-flow-key="shipment-<?=e($t['id'])?>" data-kind="shipment" data-state="<?=e($t['status'])?>" data-reference="<?=e($t['transfer_number'])?>" data-date="<?=e($t['created_at']??'')?>" data-weight="<?=e($t['quantity_kg'])?>" data-expiry="<?=e($t['expiry_date'])?>" data-search="<?=e($t['batch_number'].' '.$t['transfer_number'].' '.$t['truck_plate'].' '.$t['driver_name'])?>">
<td data-label="Référence / lot"><strong><?=e($t['transfer_number'])?></strong><small><?=e($t['batch_number'])?></small></td><td data-label="Catégorie">Envoi</td><td class="num" data-label="Poids (kg)"><strong><?=$kg($t['quantity_kg'])?></strong><small class="shipment-weight-note">vers la boucherie</small></td><td data-label="DLC"><?=e(date('d/m/Y',strtotime($t['expiry_date'])))?></td><td data-label="État"><span class="ui-status ui-status--<?=e($statusTone($t['status']))?>"><?=e($statusLabels[$t['status']]??$t['status'])?></span></td><td data-label="Transport"><?=e($t['truck_plate'])?><small class="shipment-weight-note"><?=e($t['driver_name'])?></small></td><td data-label="Détails et actions"><div class="shipment-action-stack"><button type="button" class="btn-secondary shipment-btr-trigger" data-btr-preview data-btr-url="<?=e(base_url('livestock/pigs/shipments/'.$t['id'].'/btr'))?>" data-btr-reference="<?=e($t['transfer_number'])?>" data-workspace-modal-open="flow-shipment-btr" aria-haspopup="dialog" aria-controls="flow-shipment-btr"><i class="bi bi-file-earmark-text" aria-hidden="true"></i> Voir le BTR</button>
<?php $canApprove=$t['status']==='draft'&&Auth::can('livestock','validate',(int)$t['source_site_id']);$canShip=$t['status']==='approved'&&Auth::can('livestock','update',(int)$t['source_site_id']);if($canApprove||$canShip):$inlineForm=true;$action='livestock/pigs/shipments/'.$t['id'].($canApprove?'/approve':'/dispatch');$confirm=$canApprove?'Approuver cet envoi et réserver les carcasses ?':'Confirmer le départ des carcasses vers la boucherie ?';require __DIR__.'/form_start.php';$submitLabel=$canApprove?'Approuver et réserver':'Confirmer le départ';require __DIR__.'/form_end.php';unset($inlineForm);endif;?>
</div><details class="slaughter-row-actions shipment-follow-up"><summary>Détails et suivi</summary><dl class="shipment-detail-list"><div><dt>Abattage</dt><dd><?=e($t['conversion_number'])?></dd></div><div><dt>Destination</dt><dd>Boucherie</dd></div><div><dt>Préparé le</dt><dd><?=e(date('d/m/Y H:i',strtotime($t['created_at'])))?></dd></div><?php if($t['dispatched_at']):?><div><dt>Départ enregistré</dt><dd><?=e(date('d/m/Y H:i',strtotime($t['dispatched_at'])))?></dd></div><?php endif;?><?php if($t['received_at']):?><div><dt>Réception enregistrée</dt><dd><?=e(date('d/m/Y H:i',strtotime($t['received_at'])))?></dd></div><?php endif;?></dl>
<?php if($t['status']==='in_transit'&&Auth::can('butchery','read')):?><a class="btn-secondary" href="<?=e(base_url('butchery/receipts'))?>">Suivre la réception</a><?php endif;?>
<?php if(in_array($t['status'],['draft','approved'],true)&&Auth::can('livestock','delete',(int)$t['source_site_id'])):?><details class="shipment-cancel"><summary>Annuler cet envoi</summary><?php $action='livestock/pigs/shipments/'.$t['id'].'/cancel';require __DIR__.'/cancel_form.php';?></details><?php endif;?></details></td></tr><?php endforeach;?></tbody></table></div>
